DROP POLICY "Published affiliations are public" ON public.affiliations;
CREATE POLICY "Published affiliations are public" ON public.affiliations FOR SELECT TO anon USING(is_published);
CREATE POLICY "Authenticated affiliation visibility" ON public.affiliations FOR SELECT TO authenticated USING(is_published OR private.has_role(auth.uid()));
